  leaders: [
    { n: "Aline Mbala Kabongo", r: { fr: "Cofondatrice et directrice générale", en: "Co-founder and Chief Executive" }, b: { fr: "Ancienne responsable logistique d'un distributeur de boissons. Elle a lancé Kimia en 2019 avec six motos et un numéro WhatsApp.", en: "Former logistics manager at a beverage distributor. She started Kimia in 2019 with six motorbikes and a WhatsApp number." } },
    { n: "Joël Tshimanga Ilunga", r: { fr: "Cofondateur, directeur des opérations", en: "Co-founder, Chief Operating Officer" }, b: { fr: "Dirige les coursiers et les agents, le hub de Masina et les contrats de fret aérien et routier.", en: "Runs the couriers and agents, the Masina hub and the air and road freight contracts." } },
    { n: "Esther Mukendi Lusamba", r: { fr: "Directrice administrative et financière", en: "Chief Financial Officer" }, b: { fr: "Expert-comptable. Responsable des reversements de contre-remboursement, 4 milliards de FC par mois.", en: "Chartered accountant. In charge of cash-on-delivery payouts, 4 billion FC a month." } },
    { n: "Serge Kasongo Mwenze", r: { fr: "Directeur technique", en: "Chief Technology Officer" }, b: { fr: "Ingénieur logiciel formé à Kinshasa et à Kigali. Il a conçu l'application des coursiers, le suivi en direct et l'API.", en: "Software engineer trained in Kinshasa and Kigali. He built the courier app, live tracking and the API." } },
    { n: "Rachel Bahati Kavira", r: { fr: "Directrice régionale Est", en: "Regional Director, East" }, b: { fr: "A ouvert les agences de Goma et de Bukavu en 2023 et les dirige depuis.", en: "Opened the Goma and Bukavu offices in 2023 and has run them since." } },
    { n: "Fabrice Kalenga Ngoy", r: { fr: "Directeur régional Katanga", en: "Regional Director, Katanga" }, b: { fr: "Responsable de Lubumbashi et Kolwezi, et des comptes des sous-traitants miniers.", en: "Responsible for Lubumbashi and Kolwezi, and for mining contractor accounts." } }
  ],
  timeline: [
    { y: 2019, fr: "Six motos, un numéro WhatsApp et un bureau à la Gombe. Premières livraisons de documents pour les cabinets et les banques.", en: "Six motorbikes, a WhatsApp number and an office in Gombe. First document deliveries for law firms and banks." },
    { y: 2020, fr: "Courses, repas et médicaments livrés pendant le confinement. 40 coursiers.", en: "Groceries, meals and medicines delivered during the lockdown. 40 couriers." },
    { y: 2021, fr: "Premiers contrats e-commerce avec contre-remboursement. Entrepôt de Masina.", en: "First e-commerce contracts with cash on delivery. Masina warehouse." },
    { y: 2022, fr: "Ouverture de Matadi et Boma par la route. Application mobile et suivi par SMS.", en: "Matadi and Boma open by road. Mobile app and SMS tracking." },
    { y: 2023, fr: "Fret aérien depuis N'djili. Agences de Lubumbashi, Goma et Bukavu.", en: "Air freight from N'djili. Lubumbashi, Goma and Bukavu offices." },
    { y: 2024, fr: "API pour les boutiques en ligne. Kisangani, Mbuji-Mayi et Kananga. Un million de colis dans l'année.", en: "API for online shops. Kisangani, Mbuji-Mayi and Kananga. One million parcels in the year." },
    { y: 2025, fr: "Kolwezi, Kikwit et Mbandaka. 2,1 millions de colis. Programme Kimia Moto pour les coursiers.", en: "Kolwezi, Kikwit and Mbandaka. 2.1 million parcels. Kimia Moto programme for couriers." },
    { y: 2026, fr: "Contre-remboursement reversé en 24 heures. Trente motos électriques en test.", en: "Cash on delivery paid out within 24 hours. Thirty electric motorbikes on trial." }
  ],
  news: [
    { d: "2026-09-01", cat: { fr: "Produit", en: "Product" }, t: { fr: "Le contre-remboursement est désormais reversé en 24 heures", en: "Cash on delivery is now paid out within 24 hours" }, b: { fr: ["Les montants encaissés par nos coursiers sont reversés aux boutiques le lendemain de la livraison, sur M-Pesa, Orange Money, Airtel Money ou par virement. Le délai était de sept jours.", "Les comptes de plus de 1 000 colis par mois sont payés chaque jour à 18 h."], en: ["Amounts collected by our couriers are paid to shops the day after delivery, via M-Pesa, Orange Money, Airtel Money or bank transfer. The delay used to be seven days.", "Accounts shipping more than 1,000 parcels a month are paid every day at 6 pm."] } },
    { d: "2026-07-14", cat: { fr: "Réseau", en: "Network" }, t: { fr: "Mbandaka rejoint le réseau : avion et barge", en: "Mbandaka joins the network: air and barge" }, b: { fr: ["Trois vols cargo par semaine desservent désormais Mbandaka. Les colis de plus de 100 kg partent par barge depuis Kinshasa, sur devis, en huit à douze jours.", "Le point relais Boutique Bolingo, près du port, reçoit et remet les colis du lundi au samedi."], en: ["Three cargo flights a week now serve Mbandaka. Parcels over 100 kg leave Kinshasa by barge, on quotation, in eight to twelve days.", "The Boutique Bolingo relay point, near the port, receives and hands over parcels Monday to Saturday."] } },
    { d: "2026-06-03", cat: { fr: "Environnement", en: "Environment" }, t: { fr: "Trente motos électriques en test à la Gombe", en: "Thirty electric motorbikes on trial in Gombe" }, b: { fr: ["Pendant six mois, trente coursiers de la Gombe et de Lingwala roulent sur des motos électriques rechargées au hub et à l'agence de la Gombe, avec batteries échangeables.", "Nous mesurons l'autonomie réelle, le coût par course et les pannes avant de décider d'un déploiement plus large."], en: ["For six months, thirty couriers in Gombe and Lingwala ride electric motorbikes charged at the hub and the Gombe office, with swappable batteries.", "We are measuring real range, cost per delivery and breakdowns before deciding on a wider roll-out."] } },
    { d: "2026-03-18", cat: { fr: "Sécurité", en: "Safety" }, t: { fr: "600 coursiers certifiés en sécurité routière", en: "600 couriers certified in road safety" }, b: { fr: ["Tous les coursiers de Kinshasa ont suivi la formation de deux jours : conduite défensive, port du casque et du gilet, transport des charges, conduite sous la pluie.", "Les accidents avec arrêt ont baissé de 41 % sur douze mois."], en: ["All Kinshasa couriers completed the two-day course: defensive riding, helmet and vest, carrying loads, riding in the rain.", "Lost-time accidents fell by 41% over twelve months."] } },
    { d: "2026-02-10", cat: { fr: "Résultats", en: "Results" }, t: { fr: "2,1 millions de colis livrés en 2025", en: "2.1 million parcels delivered in 2025" }, b: { fr: ["Le volume a doublé en un an, porté par le commerce en ligne à Kinshasa et le fret aérien vers Lubumbashi et Goma. 96,8 % des colis ont été livrés dans les délais annoncés.", "Kimia compte 3 400 entreprises clientes et 1 450 coursiers, agents et salariés."], en: ["Volume doubled in a year, driven by online retail in Kinshasa and air freight to Lubumbashi and Goma. 96.8% of parcels were delivered within the announced time.", "Kimia has 3,400 business customers and 1,450 couriers, agents and staff."] } },
    { d: "2025-11-05", cat: { fr: "Produit", en: "Product" }, t: { fr: "Nouvelle application : suivi en direct et lien partageable", en: "New app: live tracking and shareable link" }, b: { fr: ["Le jour de la livraison, le destinataire voit la position du coursier et reçoit un lien de suivi par SMS, sans installer l'application.", "Les expéditeurs peuvent reprogrammer une livraison ou la rediriger vers un point relais en deux clics."], en: ["On delivery day the recipient sees the courier's position and receives a tracking link by SMS, without installing the app.", "Senders can reschedule a delivery or redirect it to a relay point in two clicks."] } }
  ],
