  faqs: [
    { cat: "send", q: { fr: "Quelle taille de colis puis-je envoyer ?", en: "What size of parcel can I send?" }, a: { fr: "Jusqu'à 30 kg et 70 × 50 × 40 cm par colis, en ville comme entre les villes. Au-delà, notre service fret prend jusqu'à 500 kg par envoi, sur devis.", en: "Up to 30 kg and 70 × 50 × 40 cm per parcel, within a city or between cities. Beyond that, our freight service takes up to 500 kg per shipment, on quotation." } },
    { cat: "send", q: { fr: "Comment écrire une adresse à Kinshasa ?", en: "How do I write an address in Kinshasa?" }, a: { fr: "Commune, quartier, avenue et numéro si possible, puis un point de repère : église, école, arrêt de bus, couleur du portail. Le coursier appelle le destinataire avant d'arriver.", en: "Commune, district, avenue and number where possible, then a landmark: church, school, bus stop, gate colour. The courier calls the recipient before arriving." } },
    { cat: "send", q: { fr: "Puis-je programmer une collecte ?", en: "Can I schedule a pickup?" }, a: { fr: "Oui, jusqu'à sept jours à l'avance, par créneau de deux heures. Les comptes entreprises peuvent programmer des collectes récurrentes.", en: "Yes, up to seven days ahead, in two-hour slots. Business accounts can schedule recurring pickups." } },
    { cat: "send", q: { fr: "Et si le destinataire est absent ?", en: "What if the recipient is not there?" }, a: { fr: "Le coursier appelle deux fois et attend 10 minutes. Nouvelle tentative gratuite le lendemain, ou retrait en point relais. Après deux échecs, le colis est gardé cinq jours puis retourné.", en: "The courier calls twice and waits 10 minutes. Free second attempt the next day, or collection at a relay point. After two failures the parcel is kept five days, then returned." } },
    { cat: "track", q: { fr: "Je n'ai pas reçu de numéro de suivi.", en: "I did not receive a tracking number." }, a: { fr: "Il est envoyé par SMS dès la confirmation et visible dans l'application. Vérifiez le numéro de téléphone saisi, ou écrivez-nous sur WhatsApp avec le nom de l'expéditeur.", en: "It is sent by SMS as soon as the booking is confirmed and shown in the app. Check the phone number entered, or message us on WhatsApp with the sender's name." } },
    { cat: "track", q: { fr: "Pourquoi mon colis intervilles n'avance pas ?", en: "Why is my intercity parcel not moving?" }, a: { fr: "Les colis par avion attendent le prochain vol cargo disponible. Un vol reporté décale la livraison d'un jour ; vous recevez un SMS dès le nouveau départ.", en: "Air parcels wait for the next available cargo flight. A postponed flight delays delivery by a day; you receive an SMS as soon as it leaves." } },
    { cat: "track", q: { fr: "Puis-je changer l'adresse de livraison ?", en: "Can I change the delivery address?" }, a: { fr: "Oui, tant que le colis n'est pas en cours de livraison, depuis la page de suivi ou par WhatsApp. En ville, un changement de zone peut ajouter 3 000 FC.", en: "Yes, as long as the parcel is not out for delivery, from the tracking page or by WhatsApp. Within a city, a change of zone may add 3,000 FC." } },
    { cat: "pay", q: { fr: "Quels moyens de paiement acceptez-vous ?", en: "Which payment methods do you accept?" }, a: { fr: "M-Pesa, Orange Money, Airtel Money, Afrimoney, Visa et Mastercard, ou espèces au coursier. Les comptes entreprises reçoivent une facture mensuelle.", en: "M-Pesa, Orange Money, Airtel Money, Afrimoney, Visa and Mastercard, or cash to the courier. Business accounts receive a monthly invoice." } },
    { cat: "pay", q: { fr: "Comment fonctionne le contre-remboursement ?", en: "How does cash on delivery work?" }, a: { fr: "Le coursier encaisse le montant auprès du destinataire, en espèces ou en mobile money. Nous le reversons sous 24 heures, moins 2 % de frais (minimum 1 000 FC).", en: "The courier collects the amount from the recipient, in cash or mobile money. We pay it out within 24 hours, less a 2% fee (minimum 1,000 FC)." } },
    { cat: "pay", q: { fr: "Les prix sont-ils en francs ou en dollars ?", en: "Are prices in francs or dollars?" }, a: { fr: "En francs congolais, toutes taxes comprises. L'équivalent en dollars est affiché à titre indicatif, au taux de 2 850 FC pour 1 USD.", en: "In Congolese francs, all taxes included. The dollar equivalent is shown for information, at 2,850 FC to 1 USD." } },
    { cat: "biz", q: { fr: "Comment ouvrir un compte entreprise ?", en: "How do I open a business account?" }, a: { fr: "Remplissez le formulaire de la page Entreprises. Un conseiller vous appelle sous un jour ouvré ; prévoyez le RCCM, l'identification nationale et la pièce d'identité du gérant.", en: "Fill in the form on the Business page. An adviser calls you within one working day; have your RCCM, national ID number and the manager's identity document ready." } },
    { cat: "biz", q: { fr: "Proposez-vous une API ?", en: "Do you offer an API?" }, a: { fr: "Oui : création d'envois, tarifs, suivi, étiquettes et webhooks. L'environnement de test est gratuit ; la documentation est envoyée sur demande à api@kimia-express.cd.", en: "Yes: shipment creation, rates, tracking, labels and webhooks. The test environment is free; documentation is sent on request to api@kimia-express.cd." } },
    { cat: "claim", q: { fr: "Mon colis est arrivé abîmé.", en: "My parcel arrived damaged." }, a: { fr: "Refusez-le si possible, ou prenez des photos devant le coursier. Déposez une réclamation sous 48 heures avec le numéro de suivi.", en: "Refuse it if you can, or take photos in front of the courier. File a claim within 48 hours with the tracking number." } },
    { cat: "claim", q: { fr: "Comment suis-je indemnisé ?", en: "How am I compensated?" }, a: { fr: "Jusqu'à la valeur déclarée, dans la limite de 500 000 FC sans assurance complémentaire. Paiement par mobile money sous dix jours ouvrés après accord.", en: "Up to the declared value, capped at 500,000 FC without extra insurance. Paid by mobile money within ten working days of agreement." } },
    { cat: "claim", q: { fr: "Un coursier m'a demandé de l'argent en plus.", en: "A courier asked me for extra money." }, a: { fr: "Le prix payé à la réservation est définitif. Signalez-le tout de suite au service client : c'est une faute grave.", en: "The price paid at booking is final. Report it to customer service straight away: it is serious misconduct." } }
  ],
